import {escapeHTML as h} from './model.js?v=0.31.0';
import {formatSalary} from './salary-progression.js?v=0.31.0';
import {occupationById} from './occupation-data.js?v=0.31.0';
export const title=id=>occupationById(id)?.finance?.title||occupationById(id)?.title||id||'No career plan';
const money=n=>Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n):'Not available';
const correlation=n=>n===null||n===undefined?'unavailable':n.toFixed(3);
const ul=(rows,empty='None.')=>rows.length?'<ul>'+rows.map(t=>'<li>'+t+'</li>').join('')+'</ul>':'<p>'+empty+'</p>';
const named=rows=>rows.length?rows.map(x=>h(x.title)).join(' · '):'None';
export function renderIntermediate(r){return `<h2>3. Intermediate results · rerun</h2><p><strong>Six RIASEC scores:</strong> ${['R','I','A','S','E','C'].map((t,i)=>t+': '+(r.rawScores[i]??'not answered')+' / 40').join(' · ')}</p><p>Interest scores, not ability, percentiles, or success probabilities.</p><p><strong>Supported pathways:</strong> ${named(r.pathways)}</p><p><strong>Work-interest pathways:</strong> ${named(r.workPathways)}</p>${!r.profileComplete?'<p><strong>The profile is incomplete.</strong> No missing scores are filled in.</p>':r.flat||r.nearFlat?'<p><strong>The interest pattern is still open.</strong> No forced career recommendation.</p>':''}<h3>All field comparisons</h3>${ul(r.fieldComparisons.map(f=>'<strong>'+h(f.title)+'</strong> · r '+correlation(f.r)+' · '+(f.featured?'Featured':f.conflict?'Work-preference conflict':'Not featured')+' · daily-work interest '+(f.workConfirmed?'confirmed':'not confirmed')+(f.disliked.length?'<p>Work disliked: '+f.disliked.map(h).join(' · ')+'</p>':'')))}`;}
export function renderCareers(r){return `<h2>5. Refined career results · rerun</h2><p><strong>Suggested careers:</strong> ${named(r.professions)}</p><p><strong>Other work to try:</strong> ${named(r.taskLed)}</p>${!r.followupsComplete?'<p><strong>Follow-ups are incomplete.</strong> Choose answers or mark each remaining question not sure.</p>':''}${ul(r.inputs.professionRows.map(row=>'<strong>'+h(row.title)+'</strong> · '+(row.featured?'Suggested':row.comparisonOnly?'Related alternative · shared tasks':row.taskLead?'Work to try':'Not featured')+'<p>'+h(row.label)+' · r '+correlation(row.r)+' · '+row.taskSupport+'/'+row.taskTotal+' task questions</p>'+(row.educationTradeoff?'<p>'+h(row.educationTradeoff)+'</p>':'')+(row.scopeNotes?.length?ul(row.scopeNotes.map(h)):'')+(row.preparationConflict?'<p>Preferred preparation route conflicts with this career.</p>':'')+(row.needsRoleDetail?'<p>Specific-role preferences need more detail.</p>':'')+(row.fieldConflict?'<p>Earlier field preferences point elsewhere.</p>':'')+(row.reasons.length?'<p>Reasons: '+row.reasons.map(h).join(' · ')+'</p>':'')))}`;}
export function renderPlan(r){const p=r.plan;return `<h2>6. Final plan · rerun preview</h2><p>${h(r.planReason)}</p>`+(!p?'<p><strong>No career plan created.</strong> Explore work or refine the answers without assigning a profession.</p>':`<p><strong>Career:</strong> ${h(title(p.career.id))}</p><p><strong>Preparation:</strong> ${h(p.preparation)}</p>${ul((p.preparationDetails||[]).map(h))}<p><strong>Annual pay before tax:</strong> ${money(p.selectedSalary?.annualGross)} · ${h(p.paidTraining?.stageKey===p.salaryStage?p.paidTraining.label:p.salaryStages.find(x=>x.key===p.salaryStage)?.label||p.salaryStage)}</p><p><strong>Salary milestones:</strong> ${p.salaryStages.map(s=>h(s.label)+': '+formatSalary(s.amount)).join(' · ')}. Planning estimates unless a published employer example is identified.</p><p><strong>Austin lifestyle:</strong> ${h(p.lifestyle.title)} ${h(p.lifestyle.copy)}</p>${ul(['Income needed for the chosen lifestyle: '+(p.incomeRange?formatSalary(p.incomeRange.low)+'–'+formatSalary(p.incomeRange.high):'not available')+' / year before tax.','Estimated monthly take-home available: '+money(p.lifestyle.result.takeHome)+'.','Monthly spending and cash savings: '+money(p.lifestyle.result.spending)+'.','Monthly amount left: '+money(p.lifestyle.result.remaining)+'.'])}<h3>Next steps & earlier work</h3>${ul(p.steps.map(a=>'<strong>'+h(a.title)+'</strong> · '+(a.done?'Completed':'Open')+'<p>'+h(a.detail)+'</p>'+(a.notice?'<p>Notes: '+h(a.notice)+'</p>':'')))}<details><summary>Full rerun plan text · education costs, sources, budget & earlier work</summary>${ul(p.fullText.map(h))}</details>`);}
function changes(before,after){const oldIds=new Set(before.map(x=>x.id)),newIds=new Set(after.map(x=>x.id));return [...after.filter(x=>!oldIds.has(x.id)).map(x=>'Added: '+h(x.title)),...before.filter(x=>!newIds.has(x.id)).map(x=>'Removed: '+h(x.title))];}
export function renderComparison(before,after,edited){const pathChanges=changes(before.pathways,after.pathways),careerChanges=changes(before.professions,after.professions);return `<h3>Original → rerun</h3><p><strong>RIASEC:</strong> ${['R','I','A','S','E','C'].map((t,i)=>t+' '+(before.rawScores[i]??'?')+' → '+(after.rawScores[i]??'?')).join(' · ')}</p><p><strong>Pathways:</strong> ${named(before.pathways)} → ${named(after.pathways)}</p>${ul(pathChanges,'No pathways added or removed.')}<p><strong>Work-interest pathways:</strong> ${named(before.workPathways)} → ${named(after.workPathways)}</p><p><strong>Career suggestions:</strong> ${named(before.professions)} → ${named(after.professions)}</p>${ul(careerChanges,'No careers added or removed.')}<p><strong>Plan career:</strong> ${h(title(before.plan?.career.id))} → ${h(title(after.plan?.career.id))}</p><p><strong>Plan annual gross:</strong> ${money(before.plan?.selectedSalary?.annualGross)} → ${money(after.plan?.selectedSalary?.annualGross)}</p><p><strong>Monthly spending:</strong> ${money(before.plan?.lifestyle.result.spending)} → ${money(after.plan?.lifestyle.result.spending)}</p><details><summary>Changed answers (${edited.length})</summary>${ul(edited.map(e=>'<strong>'+h(e.prompt)+'</strong><p>'+h(e.before)+' → '+h(e.after)+'</p>'),'No answer changes.')}</details><p><a href="#intermediate">Updated pathways ↓</a> · <a href="#refined">Updated careers ↓</a> · <a href="#plan">Updated plan ↓</a></p>`;}
